import urllib.request, urllib.error, json, time, datetime, email.utils
from decimal import Decimal, ROUND_HALF_UP
BASE='http://localhost:8080'
token=None
stats={}
def get(path,auth=True):
 global token
 while True:
  if auth and token is None:
   token=get('/token',False)['token']
  req=urllib.request.Request(BASE+path,method='GET' if auth else 'POST',headers={'Authorization':'Bearer '+token} if auth else {})
  try:
   with urllib.request.urlopen(req,timeout=30) as r: return json.load(r)
  except urllib.error.HTTPError as e:
   body=e.read().decode(); stats[str(e.code)]=stats.get(str(e.code),0)+1
   if e.code==401 and auth:
    token=None
    continue
   retry=e.headers.get('Retry-After')
   if retry:
    try: delay=float(retry)
    except ValueError: delay=max(0,(email.utils.parsedate_to_datetime(retry)-datetime.datetime.now(datetime.timezone.utc)).total_seconds())
   else:
    try:
     b=json.loads(body); delay=float(b.get('retry_after',1))
    except Exception: delay=1
   print('retry',path,e.code,'wait',delay,body,flush=True)
   time.sleep(max(0,delay))
  except (urllib.error.URLError,TimeoutError) as e:
   print('retry transport',path,str(e),flush=True); time.sleep(1)
orders={}; duplicates=0; conflicts=[]; pages=[]; path='/orders?page=1'
