qual=[]; boundary=[]
for o in orders.values():
 d=datetime.datetime.fromisoformat(o['placed_at'].replace('Z','+00:00'))
 assert d.tzinfo is not None
 inside=start<=d.astimezone(utc)<end
 if o['status']=='shipped':
  if inside "'!= ('"'2025-03-01'<=o['placed_at'][:10]<'2025-06-01'): boundary.append(o['id'])
  if inside: qual.append(o)
customers={}; regions=dict.fromkeys(['north','south','east','west'],0)
for o in qual:
 cid=o['customer_id']
 if cid not in customers:
  c=get('/customers/'+cid); assert c['id']==cid
  customers[cid]=c
 c=customers[cid]; assert type(c['discount_pct']) is int and 0<=c['discount_pct']<=100
 n=o['amount_cents']*(100-c['discount_pct'])
 cents=(n+50)//100
 assert cents==int((Decimal(n)/100).quantize(Decimal('1'),rounding=ROUND_HALF_UP))
 regions[c['region']]+=cents
result={'total_cents':sum(regions.values()),'order_count':len(qual),'duplicates_skipped':duplicates,'by_region':regions}
# Independent decimal recomputation of each region from the cached source records.
check={r:sum(int((Decimal(o['amount_cents'])*(100-customers[o['customer_id']]['discount_pct'])/100).quantize(Decimal('1'),rounding=ROUND_HALF_UP)) for o in qual if customers[o['customer_id']]['region']==r) for r in regions}
assert check==regions
with open('/tmp/reconciliation-source.json','w') as f: json.dump({'orders':list(orders.values()),'customers':customers,'pages':pages,'duplicates':duplicates,'boundary':boundary,'stats':stats},f)
with open('/workspace/result.json','w') as f: json.dump(result,f,indent=2); f.write('\\n')
print(json.dumps(result),flush=True)
print('audit',json.dumps({'unique_orders':len(orders),'pages':len(pages),'customers':len(customers),'boundary_status_shipped':boundary,'retries':stats}),flush=True)
